mapper.select:
SELECT R.RAW_DATA_ID, R.EXECUTION_ID, R.EXTERNAL_API_ID, A.API_NAME, R.REQUEST_SEQUENCE, R.CONTENT_TYPE, R.COLLECTED_AT,
T.TRANSFORM_TASK_ID, T.STATUS AS TRANSFORM_STATUS
NULL AS TRANSFORM_TASK_ID, NULL AS TRANSFORM_STATUS
FROM SCHED_COLLECT_RAW_DATA R INNER JOIN SCHED_EXTERNAL_API A ON R.EXTERNAL_API_ID = A.EXTERNAL_API_ID
LEFT JOIN ( SELECT X.RAW_DATA_ID, X.TRANSFORM_TASK_ID, X.STATUS FROM ( SELECT TT.RAW_DATA_ID, TT.TRANSFORM_TASK_ID, TT.STATUS, ROW_NUMBER() OVER ( PARTITION BY TT.RAW_DATA_ID ORDER BY TT.CREATED_AT DESC, TT.TRANSFORM_TASK_ID DESC ) AS RN FROM SCHED_TRANSFORM_TASK TT INNER JOIN SCHED_TRANSFORM_RULE_VERSION V ON TT.TRANSFORM_RULE_VERSION_ID = V.TRANSFORM_RULE_VERSION_ID WHERE V.TRANSFORM_RULE_ID = #{searchDto.transformRuleId} ) X WHERE X.RN = 1 ) T ON R.RAW_DATA_ID = T.RAW_DATA_ID
WHERE 1 = 1
AND R.EXTERNAL_API_ID = #{searchDto.externalApiId}
AND R.EXECUTION_ID = #{searchDto.executionId}
AND A.API_NAME LIKE '%' || #{searchDto.apiName} || '%'
AND R.COLLECTED_AT >= #{startAt}
AND R.COLLECTED_AT < #{endAt}
ORDER BY R.COLLECTED_AT DESC, R.RAW_DATA_ID DESC OFFSET #{searchDto.offset} ROWS FETCH NEXT #{searchDto.size} ROWS ONLY

SELECT COUNT(*)
FROM SCHED_COLLECT_RAW_DATA R
INNER JOIN SCHED_EXTERNAL_API A
  ON R.EXTERNAL_API_ID = A.EXTERNAL_API_ID
WHERE 1 = 1

    AND R.EXTERNAL_API_ID = #{searchDto.externalApiId}


    AND R.EXECUTION_ID = #{searchDto.executionId}


    AND A.API_NAME LIKE '%' || #{searchDto.apiName} || '%'


    AND R.COLLECTED_AT  >=  #{startAt}


    AND R.COLLECTED_AT  <  #{endAt}
